CREATE TABLE IF NOT EXISTS `playerbot_farming_spot` (
  `ZoneId` int NOT NULL DEFAULT '0',
  `Id` int NOT NULL AUTO_INCREMENT,
  `MinLevel` int NOT NULL DEFAULT '0',
  `MaxLevel` int NOT NULL DEFAULT '0',
  `TeamsDisabled` int NOT NULL DEFAULT '0',
  `X` float NOT NULL DEFAULT '0',
  `Y` float NOT NULL DEFAULT '0',
  `Z` float NOT NULL DEFAULT '0',
  `Radius` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`Id`,`ZoneId`)
) ENGINE=InnoDB AUTO_INCREMENT=8234 DEFAULT CHARSET=latin1;

DELETE FROM `playerbot_farming_spot`;
